{
  "assessment": null,
  "block_plan": {
    "blocks": [
      {
        "adapts_to": [
          "sensing",
          "interested",
          "visual"
        ],
        "block_id": "b1_anchor_scenario",
        "block_type": "anchor_scenario",
        "chosen_by": "[B]",
        "payload": {
          "scenario": "某智能制造企业研发中心做出协同机器人关节模组：内部谐波减速器结构改进、配套视觉伺服控制方法，外壳做了流线型工业设计。项目经理下周要参加国内工业展，同时打算提交中国专利申请。团队争论三件事——这算发明还是实用新型？展会一亮相会不会把“家底”公开？中国专利管不管得了海外客户仿制？冲突点同时指向保护客体、权利特征和制度边界。",
          "think_prompt": "如果现在只能先回答一个问题，你觉得应先分清“能申请什么类型”还是先担心“展会公开”？为什么？",
          "why_anchor": "用同一智能制造技术事实锚定本节核心：三种保护客体、专利权三大特征与中国专利制度体系。"
        },
        "rationale": "sensing强偏好具象事实，冷启动用智能制造冲突降低抽象门槛",
        "source": "learner_profile.style.perception + cold_start",
        "title": "智能制造场景锚定：机器人关节要不要、怎么申请",
        "trigger": "perception=sensing(0.86) / cold_start"
      },
      {
        "adapts_to": [
          "sequential",
          "remember"
        ],
        "block_id": "b2_legal_anchor",
        "block_type": "legal_anchor",
        "chosen_by": "[B]",
        "payload": {
          "articles": [
            {
              "article": "《专利法》第二条（发明、实用新型、外观设计定义）",
              "source": "《中华人民共和国专利法》第二条"
            },
            {
              "article": "《专利法》第一条（立法目的：保护权益、鼓励创造、推动应用、促进发展）",
              "source": "《中华人民共和国专利法》第一条"
            }
          ],
          "plain_summary": [
            "第二条用人话说：发明=产品、方法或者其改进的新的技术方案；实用新型=产品形状、构造或者其结合所提出的适于实用的新的技术方案；外观设计=对产品的整体或者局部的形状、图案或者其结合以及色彩与形状、图案的结合所作出的富有美感并适于工业应用的新设计。",
            "第一条规定了保护专利权人的合法权益、鼓励发明创造、推动发明创造的应用、提高创新能力以及促进科学技术进步和经济社会发展的立法目的。"
          ],
          "why_it_matters": "本节地基就是“保护什么”和“为什么保护”。没有第二条客体边界，后续新颖性与侵权全无抓手；没有第一条，难以理解公开换保护的制度逻辑。"
        },
        "rationale": "法条溯源闸门，强制回扣可核验条文",
        "source": "mandatory_legal_anchor",
        "title": "法条锚定：第二条客体与第一条立法目的",
        "trigger": "mandatory"
      },
      {
        "adapts_to": [
          "sensing",
          "apply",
          "application_gap"
        ],
        "block_id": "b3_worked_example",
        "block_type": "worked_example",
        "chosen_by": "[B]",
        "payload": {
          "applicable_rule": "《专利法》第二条；专利权独占性、时间性、地域性通说",
          "conclusion": "甲发明、乙实用新型（或发明）、丙外观设计；客体分类完成后，再用独占/时间/地域理解权利边界。",
          "problem": "智能工厂交付三项成果：（甲）视觉伺服控制方法；（乙）谐波减速器齿形结构改进；（丙）机器人关节外壳流线造型。问：分别最可能落入哪种专利保护客体？并说明与制度特征的关联。",
          "steps": [
            {
              "reasoning": "甲是方法技术方案，不属于产品形状构造，不能走实用新型，只能考虑发明。",
              "summary": "方法→发明客体"
            },
            {
              "reasoning": "乙是产品结构改进且适于实用，可归实用新型；若技术方案高度完整也可选发明。",
              "summary": "结构产品→实用新型/发明"
            },
            {
              "reasoning": "丙是外观美感+工业应用，走外观设计。",
              "summary": "外观→外观设计"
            },
            {
              "reasoning": "无论哪一类，中国授权后效力原则上限于中国（地域性），且有法定期限（时间性），未经许可不得为生产经营目的实施（独占性）。",
              "summary": "三类均受三大特征约束"
            }
          ],
          "takeaway": "智能制造案例先按第二条分客体，再叠三大特征，避免一上来就跳到新颖性或侵权。"
        },
        "rationale": "apply偏低且冷启动，完整演示判定链",
        "source": "cognition.apply + cold_start",
        "title": "案例演示：机器人关节三成果如何归类",
        "trigger": "cold_start(low_confidence)"
      },
      {
        "adapts_to": [
          "visual",
          "sequential"
        ],
        "block_id": "b4_decision_flow",
        "block_type": "decision_flow",
        "chosen_by": "[B]",
        "payload": {
          "end_states": [
            "归入发明",
            "归入实用新型",
            "归入外观设计",
            "需调整客体选择或补充材料",
            "明确仅中国有效且有期限"
          ],
          "question": "面对一项智能制造技术成果，如何快速落入专利法律制度基础框架？",
          "steps": [
            {
              "condition": "成果主要是方法或完整产品/方法新方案？",
              "outcome": "优先考虑发明客体"
            },
            {
              "condition": "成果是产品形状、构造或其结合且适于实用？",
              "outcome": "可考虑实用新型（方法不可）"
            },
            {
              "condition": "成果是产品外观（形状/图案/色彩结合）富有美感并适于工业应用？",
              "outcome": "考虑外观设计"
            },
            {
              "condition": "已初步锁定客体后，检查效力边界",
              "outcome": "叠加独占性（未经许可不得实施）、时间性（有期限）、地域性（中国专利管中国）"
            },
            {
              "condition": "需要查依据时",
              "outcome": "原则看专利法→程序看实施细则→审查操作看审查指南；发明申请经初步审查后，依法提出实质审查请求并进行实质审查，实用新型和外观设计主要实行初步审查"
            }
          ]
        },
        "rationale": "视觉偏好用分支步骤替代长段落",
        "source": "style.input.visual",
        "title": "决策流：智能制造方案如何落入制度框架",
        "trigger": "input=visual(0.82)"
      },
      {
        "adapts_to": [
          "sequential",
          "remember"
        ],
        "block_id": "b5_mnemonic",
        "block_type": "mnemonic",
        "chosen_by": "[B]",
        "payload": {
          "device": "客体三兄弟：发（方法产品新方案）/实（结构实用）/外（好看量产）；特征口诀：独时地；体系三层：法—细—指；审查双轨：发实审、实外初审。",
          "mapping": [
            {
              "explanation": "发明：产品、方法或者其改进的新的技术方案",
              "term": "发"
            },
            {
              "explanation": "实用新型：产品形状、构造或者其结合所提出的适于实用的新的技术方案",
              "term": "实"
            },
            {
              "explanation": "外观设计：对产品的整体或者局部的形状、图案或者其结合以及色彩与形状、图案的结合所作出的富有美感并适于工业应用的新设计",
              "term": "外"
            },
            {
              "explanation": "独占性：未经许可不得为生产经营目的实施",
              "term": "独"
            },
            {
              "explanation": "时间性：法定期限届满权利终止",
              "term": "时"
            },
            {
              "explanation": "地域性：效力原则上限于授权地域",
              "term": "地"
            },
            {
              "explanation": "专利法、实施细则、审查指南三级规范",
              "term": "法细指"
            },
            {
              "explanation": "发明申请经初步审查后，依法提出实质审查请求并进行实质审查；实用新型和外观设计主要实行初步审查",
              "term": "双轨"
            }
          ],
          "when_recall": "看到智能制造题干要选类型、或问“中国专利管不管海外/过期怎么办/依据哪份文件”时立刻调出口诀。"
        },
        "rationale": "顺序型学习者适合可逐步展开的分类口诀",
        "source": "style.understanding.sequential",
        "title": "口诀：客体三兄弟 + 独时地 + 法细指",
        "trigger": "understanding=sequential(0.71)"
      },
      {
        "adapts_to": [
          "reflective",
          "interested"
        ],
        "block_id": "b6_reflect_prompt",
        "block_type": "reflect_prompt",
        "chosen_by": "[B]",
        "payload": {
          "connect": "连接已有研发经验与本节“客体—特征—体系—作用—双轨审查”框架，为下一节点专利权保护做铺垫",
          "question": "回想你参与或了解过的智能制造项目，如果当时要做专利布局，你会先问团队哪三个制度基础问题？",
          "what_to_notice": [
            "成果更像方法、结构还是外观",
            "权利是否只在中国有效、期限是否匹配产品生命周期",
            "查规则时应先翻专利法还是直接看审查指南"
          ]
        },
        "rationale": "反思型加工偏好先内化再迁移",
        "source": "style.processing.reflective",
        "title": "反思：从产线经验映射制度框架",
        "trigger": "processing=reflective(0.67)"
      },
      {
        "adapts_to": [
          "application_gap"
        ],
        "block_id": "b7_assessment",
        "block_type": "assessment",
        "chosen_by": "[B]",
        "payload": {
          "body_guide": "本节设有测评（覆盖向后复习/向前探测/薄弱点），请到【习题】区作答。",
          "coverage": {
            "backward_review": true,
            "forward_probe": true,
            "weakness_probe": true
          },
          "items": [
            {
              "qid": "q1",
              "summary": "智能制造情境下辨识专利权三大特征（向后复习L1）"
            },
            {
              "qid": "q2",
              "summary": "探测专利权效力基本表述（向前探测L1）"
            },
            {
              "qid": "q3",
              "summary": "三项智能制造成果的客体归类辨析（薄弱点L3）"
            }
          ]
        },
        "rationale": "强制三类覆盖闭环",
        "source": "question_scope",
        "title": "三类测评入口",
        "trigger": "mandatory"
      },
      {
        "adapts_to": [
          "sequential",
          "global"
        ],
        "block_id": "b8_knowledge_synthesis",
        "block_type": "knowledge_synthesis",
        "chosen_by": "[B]",
        "payload": {
          "framework": [
            "基本特征：独占性、时间性、地域性——理解专利权边界的三把尺子",
            "制度体系：专利法（原则）—实施细则（程序）—审查指南（操作）",
            "三种客体：发明、实用新型、外观设计（《专利法》第二条）",
            "制度作用：激励创造、促进公开、推动应用与经济发展",
            "发展特点：早期公开延迟审查；初步审查与实质审查并行"
          ],
          "key_relations": [
            "先定客体（第二条）→再理解特征（独时地）→再认体系文件与审查双轨→才能进入后续授权条件与保护",
            "制度作用解释‘为什么要公开’，公开换保护是专利制度的一般机制，与后续新颖性现有技术概念衔接"
          ],
          "must_know": [
            "方法方案不能走实用新型",
            "中国专利原则上只管中国（地域性）",
            "发明申请经初步审查后，依法提出实质审查请求并进行实质审查；实用新型与外观设计主要实行初步审查",
            "公开换保护是专利制度的一般机制，不是无条件垄断"
          ]
        },
        "rationale": "建立结构而非碎片，覆盖全部知识要点",
        "source": "mandatory_knowledge_synthesis",
        "title": "知识综合：专利法律制度基础框架",
        "trigger": "mandatory"
      },
      {
        "adapts_to": [
          "visual",
          "sensing"
        ],
        "block_id": "b9_summary_card",
        "block_type": "summary_card",
        "chosen_by": "[B]",
        "payload": {
          "cards": [
            {
              "concept": "三种客体",
              "one_liner": "发明=方案；实用新型=实用结构；外观设计=工业美感外观"
            },
            {
              "concept": "三大特征",
              "one_liner": "独占、有期限、原则上有国界"
            },
            {
              "concept": "三级体系",
              "one_liner": "法定原则、细则定程序、指南定审查操作"
            },
            {
              "concept": "制度作用",
              "one_liner": "激励创造+公开换保护+推动应用与经济"
            },
            {
              "concept": "审查特点",
              "one_liner": "早期公开延迟审查；发明申请经初步审查后依法提出实质审查请求，实用新型与外观设计主要实行初步审查"
            }
          ],
          "must_recite": [
            "《专利法》第二条三种客体定义要点",
            "独占性、时间性、地域性",
            "专利法—实施细则—审查指南",
            "发明申请经初步审查后依法提出实质审查请求并进行实质审查；实用新型与外观设计主要实行初步审查"
          ],
          "one_line": "智能制造方案先分客体，再套独时地，顺着法细指进入双轨审查——这就是专利法律制度基础。"
        },
        "rationale": "子点较多，用速查卡收口便于复盘",
        "source": "summary_card_rule",
        "title": "速查卡：本节带走清单",
        "trigger": "len(knowledge_sub_nodes)=3>=3"
      }
    ],
    "budget": {
      "adaptive_max": 6,
      "adaptive_used": 6,
      "total": 9,
      "total_max": 9
    },
    "debate_resolved": true,
    "learner_id": "eee91b7e899f4a0f8b6affea68a87492",
    "node": "patent-law-foundation",
    "order": [
      "b1_anchor_scenario",
      "b2_legal_anchor",
      "b3_worked_example",
      "b4_decision_flow",
      "b5_mnemonic",
      "b6_reflect_prompt",
      "b7_assessment",
      "b8_knowledge_synthesis",
      "b9_summary_card"
    ]
  },
  "draft_stage": "integration",
  "exercises": [
    {
      "answer": "B",
      "options": [
        "A. 获得中国专利后，在欧盟展会销售仿制品也自动构成侵权",
        "B. 专利权具有独占性、时间性和地域性，中国专利效力原则上仅及于中国境内",
        "C. 实用新型保护期限与发明相同，均为自申请日起20年",
        "D. 外观设计不受时间性限制，可无限期续展"
      ],
      "question": "某智能制造企业就“协同机器人关节模组的新型谐波减速器结构”拟在中国申请专利。关于专利制度基本特征，下列说法正确的是？"
    },
    {
      "answer": "C",
      "options": [
        "A. （1）实用新型；（2）外观设计；（3）发明",
        "B. （1）外观设计；（2）发明；（3）实用新型",
        "C. （1）发明；（2）实用新型或发明；（3）外观设计",
        "D. 三项均可仅以实用新型一种类型全部覆盖"
      ],
      "question": "智能产线团队同时完成三项成果：（1）一种视觉定位控制方法；（2）夹爪机械结构改进；（3）设备外壳流线造型。若严格按《专利法》第二条区分保护客体，下列对应最准确的是？"
    }
  ],
  "expert": "expert_b",
  "interactive_questions": [
    {
      "answer": "B",
      "category": "understand",
      "difficulty": "L1",
      "kc_node_id": "patent-law-foundation",
      "options": [
        "A. 获得中国专利后，在欧盟展会销售仿制品也自动构成侵权",
        "B. 专利权具有独占性、时间性和地域性，中国专利效力原则上仅及于中国境内",
        "C. 实用新型保护期限与发明相同，均为自申请日起20年",
        "D. 外观设计不受时间性限制，可无限期续展"
      ],
      "qid": "q1",
      "question": "某智能制造企业就“协同机器人关节模组的新型谐波减速器结构”拟在中国申请专利。关于专利制度基本特征，下列说法正确的是？",
      "source_tag": "backward_review"
    },
    {
      "answer": "A",
      "category": "remember",
      "difficulty": "L1",
      "kc_node_id": "patent-rights-protection",
      "options": [
        "A. 任何单位或者个人未经专利权人许可，都不得实施其专利（为生产经营目的）",
        "B. 任何人都可以免费实施，只要标注来源",
        "C. 只有出口行为才可能构成侵权",
        "D. 保护范围一律以说明书附图为准，与权利要求无关"
      ],
      "qid": "q2",
      "question": "关于专利权保护的初步认识（下一节点探测），发明和实用新型专利权被授予后，下列哪一表述更接近《专利法》对权利效力的基本规定？",
      "source_tag": "forward_probe"
    },
    {
      "answer": "C",
      "category": "analyze",
      "difficulty": "L3",
      "kc_node_id": "patent-law-foundation",
      "options": [
        "A. （1）实用新型；（2）外观设计；（3）发明",
        "B. （1）外观设计；（2）发明；（3）实用新型",
        "C. （1）发明；（2）实用新型或发明；（3）外观设计",
        "D. 三项均可仅以实用新型一种类型全部覆盖"
      ],
      "qid": "q3",
      "question": "智能产线团队同时完成三项成果：（1）一种视觉定位控制方法；（2）夹爪机械结构改进；（3）设备外壳流线造型。若严格按《专利法》第二条区分保护客体，下列对应最准确的是？",
      "source_tag": "weakness_probe"
    }
  ],
  "irac": {
    "application": "以协同机器人关节为例：结构改进可归实用新型或发明，方法控制归发明，外壳归外观设计；权利仅在授权国有效且有期限；公开换保护体现制度激励作用。",
